import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= length) {
            length = input.read(buffer)
            ptr = 0
            if (length <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var result = 0L
        while (c > 32 && c != -1) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return result
    }
}

private fun modPow(baseValue: Long, exponentValue: Long, mod: Long): Long {
    var base = baseValue % mod
    var exponent = exponentValue
    var result = 1L

    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = result * base % mod
        }
        base = base * base % mod
        exponent = exponent shr 1
    }
    return result
}

private fun multiplyPolynomials(
    a: LongArray,
    b: LongArray,
    maxDegree: Int,
    mod: Long
): LongArray {
    val result = LongArray(maxDegree + 1)

    for (i in 0..maxDegree) {
        if (a[i] == 0L) continue
        val limit = maxDegree - i
        for (j in 0..limit) {
            if (b[j] == 0L) continue
            result[i + j] = (result[i + j] + a[i] * b[j] % mod) % mod
        }
    }
    return result
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextLong().toInt()
    val m = fs.nextLong().toInt()
    val mod = fs.nextLong()

    val factorial = LongArray(m + 1)
    val inverseFactorial = LongArray(m + 1)
    factorial[0] = 1L

    for (i in 1..m) {
        factorial[i] = factorial[i - 1] * i.toLong() % mod
    }

    inverseFactorial[m] = modPow(factorial[m], mod - 2, mod)
    for (i in m downTo 1) {
        inverseFactorial[i - 1] = inverseFactorial[i] * i.toLong() % mod
    }

    fun combination(total: Int, choose: Int): Long {
        return factorial[total] *
            inverseFactorial[choose] % mod *
            inverseFactorial[total - choose] % mod
    }

    val ways = LongArray(m + 1)
    val madness = LongArray(m + 1)
    ways[0] = 1L

    for (size in 1..m) {
        var waysSum = 0L
        var madnessSum = 0L

        for (left in 0 until size) {
            val right = size - 1 - left
            val interleavings = combination(size - 1, left)
            val baseWays = ways[left] * ways[right] % mod

            waysSum = (waysSum + interleavings * baseWays % mod) % mod

            val previousMadness = (
                madness[left] * ways[right] % mod +
                    ways[left] * madness[right] % mod
                ) % mod

            val transitionWays = size.toLong() + 1L
            val transitionMadness =
                left.toLong() * (left + 1L) / 2L +
                    right.toLong() * (right + 1L) / 2L

            val contribution = (
                previousMadness * transitionWays % mod +
                    (transitionMadness % mod) * baseWays % mod
                ) % mod

            madnessSum = (
                madnessSum + interleavings * contribution % mod
                ) % mod
        }

        ways[size] = (size.toLong() + 1L) * waysSum % mod
        madness[size] = madnessSum
    }

    val blockWays = LongArray(m + 1)
    val blockMadness = LongArray(m + 1)

    for (size in 1..m) {
        blockWays[size] = ways[size] * inverseFactorial[size] % mod
        blockMadness[size] = madness[size] * inverseFactorial[size] % mod
    }

    var basePolynomial = LongArray(m + 1)
    basePolynomial[0] = 1L
    for (i in 1..m) {
        basePolynomial[i] = blockWays[i]
    }

    var resultPolynomial = LongArray(m + 1)
    resultPolynomial[0] = 1L

    var exponent = n - m
    while (exponent > 0) {
        if ((exponent and 1) != 0) {
            resultPolynomial = multiplyPolynomials(
                resultPolynomial,
                basePolynomial,
                m,
                mod
            )
        }
        exponent = exponent shr 1
        if (exponent > 0) {
            basePolynomial = multiplyPolynomials(
                basePolynomial,
                basePolynomial,
                m,
                mod
            )
        }
    }

    var coefficient = 0L
    for (size in 1..m) {
        coefficient = (
            coefficient +
                blockMadness[size] * resultPolynomial[m - size] % mod
            ) % mod
    }

    val availableGaps = (n - m + 1).toLong()
    val answer = factorial[m] *
        (availableGaps % mod) % mod *
        coefficient % mod

    print(answer)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private fun mul(a: Long, b: Long, mod: Long): Long = (a * b) % mod

private fun modPow(baseValue: Long, exponentValue: Long, mod: Long): Long {
    var base = baseValue % mod
    var exponent = exponentValue
    var result = 1L
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) result = mul(result, base, mod)
        base = mul(base, base, mod)
        exponent = exponent shr 1
    }
    return result
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()
    val mod = st.nextToken().toLong()

    val limit = n + 1
    val fact = LongArray(limit + 1)
    val invFact = LongArray(limit + 1)

    fact[0] = 1L
    for (i in 1..limit) {
        fact[i] = mul(fact[i - 1], i.toLong(), mod)
    }

    invFact[limit] = modPow(fact[limit], mod - 2, mod)
    for (i in limit downTo 1) {
        invFact[i - 1] = mul(invFact[i], i.toLong(), mod)
    }

    fun combination(x: Int, y: Int): Long {
        if (y < 0 || y > x) return 0L
        return mul(fact[x], mul(invFact[y], invFact[x - y], mod), mod)
    }

    val pow2 = LongArray(m + 1)
    pow2[0] = 1L
    for (i in 1..m) pow2[i] = (pow2[i - 1] * 2L) % mod

    val f = LongArray(m + 1)
    f[0] = 1L
    for (s in 1..m) {
        f[s] = mul(
            mul(pow2[s], modPow((s + 1).toLong(), (s - 1).toLong(), mod), mod),
            invFact[s],
            mod
        )
    }

    val g = LongArray(m + 1)
    for (s in 1..m) {
        var convolution = 0L
        var distanceConvolution = 0L

        for (left in 0 until s) {
            val right = s - 1 - left

            convolution += mul(g[left], f[right], mod)
            if (convolution >= mod) convolution -= mod

            val triangular = left.toLong() * (left + 1L) / 2L % mod
            distanceConvolution += mul(
                triangular,
                mul(f[left], f[right], mod),
                mod
            )
            if (distanceConvolution >= mod) distanceConvolution -= mod
        }

        val first = mul((2L * (s + 1L)) % mod, convolution, mod)
        val second = mul(2L, distanceConvolution, mod)
        g[s] = mul((first + second) % mod, modPow(s.toLong(), mod - 2, mod), mod)
    }

    fun powerCoefficient(blocks: Int, degree: Int): Long {
        if (degree == 0) return 1L
        if (blocks == 0) return 0L

        return mul(
            mul(
                pow2[degree],
                blocks.toLong(),
                mod
            ),
            mul(
                modPow((blocks + degree).toLong(), (degree - 1).toLong(), mod),
                invFact[degree],
                mod
            ),
            mod
        )
    }

    var answer = 0L
    val maxRuns = minOf(m, n - m + 1)

    for (runs in 1..maxRuns) {
        var coefficient = 0L

        for (blockSize in 1..m) {
            val remainingDegree = m - blockSize
            val term = mul(
                g[blockSize],
                powerCoefficient(runs - 1, remainingDegree),
                mod
            )
            coefficient += term
            if (coefficient >= mod) coefficient -= mod
        }

        var contribution = mul(fact[m], runs.toLong(), mod)
        contribution = mul(contribution, coefficient, mod)
        contribution = mul(contribution, combination(n - m + 1, runs), mod)

        answer += contribution
        if (answer >= mod) answer -= mod
    }

    print(answer)
}

import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextInt(): Int {
        var c = readByte()
        while (c <= 32) c = readByte()
        var value = 0
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

private fun multiply(
    a: LongArray,
    b: LongArray,
    limit: Int,
    mod: Long
): LongArray {
    val result = LongArray(limit + 1)
    for (i in 0..limit) {
        val ai = a[i]
        if (ai == 0L) continue
        val maxJ = limit - i
        for (j in 0..maxJ) {
            val bj = b[j]
            if (bj == 0L) continue
            val index = i + j
            val add = (ai * bj) % mod
            var value = result[index] + add
            if (value >= mod) value -= mod
            result[index] = value
        }
    }
    return result
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextInt()
    val mod = fs.nextInt().toLong()

    val inv = LongArray(m + 1)
    if (m >= 1) inv[1] = 1L
    for (i in 2..m) {
        inv[i] = (mod - ((mod / i) * inv[(mod % i).toInt()]) % mod) % mod
    }

    val ways = LongArray(m + 1)
    val madness = LongArray(m + 1)
    ways[0] = 1L

    for (k in 1..m) {
        var sumWays = 0L
        var sumMadness = 0L
        val width = k + 1L

        for (left in 0 until k) {
            val right = k - 1 - left
            val wl = ways[left]
            val wr = ways[right]

            var addWays = (wl * wr) % mod
            sumWays += addWays
            if (sumWays >= mod) sumWays -= mod

            val displacement =
                (left.toLong() * (left + 1L) / 2L +
                 right.toLong() * (right + 1L) / 2L) % mod

            var rootCost = (displacement * wl) % mod
            rootCost = (rootCost * wr) % mod

            var childCost =
                ((madness[left] * wr) % mod + (wl * madness[right]) % mod) % mod
            childCost = (childCost * width) % mod

            var addMadness = rootCost + childCost
            if (addMadness >= mod) addMadness -= mod

            sumMadness += addMadness
            if (sumMadness >= mod) sumMadness -= mod
        }

        ways[k] = (((sumWays * width) % mod) * inv[k]) % mod
        madness[k] = (sumMadness * inv[k]) % mod
    }

    val freeGapChoices = n - m + 1
    var exponent = freeGapChoices - 1
    var base = ways.copyOf()
    var power = LongArray(m + 1)
    power[0] = 1L

    while (exponent > 0) {
        if ((exponent and 1) != 0) {
            power = multiply(power, base, m, mod)
        }
        exponent = exponent shr 1
        if (exponent > 0) {
            base = multiply(base, base, m, mod)
        }
    }

    var coefficient = 0L
    for (k in 1..m) {
        val add = (madness[k] * power[m - k]) % mod
        coefficient += add
        if (coefficient >= mod) coefficient -= mod
    }

    coefficient = (coefficient * freeGapChoices.toLong()) % mod

    var factorial = 1L
    for (i in 2..m) {
        factorial = (factorial * i.toLong()) % mod
    }

    val answer = (coefficient * factorial) % mod
    print(answer)
}

