    for (i in m downTo 1) {
        inverseFactorial[i - 1] = inverseFactorial[i] * i.toLong() % mod
    }

    val rawWays = LongArray(m + 1)
    val rawMadness = LongArray(m + 1)
    rawWays[0] = 1L

    for (size in 1..m) {
        var totalWays = 0L
        var totalMadness = 0L
        val transitionWays = (size + 1).toLong()

        for (left in 0 until size) {
            val right = size - 1 - left
            val interleavings = choose[size - 1][left]

            val baseWays = rawWays[left] * rawWays[right] % mod

            var waysTerm = interleavings * baseWays % mod
            waysTerm = waysTerm * transitionWays % mod
            totalWays += waysTerm
            if (totalWays >= mod) totalWays -= mod

            var previousMadness =
                rawMadness[left] * rawWays[right] % mod +
                    rawWays[left] * rawMadness[right] % mod
            if (previousMadness >= mod) previousMadness -= mod

            val leftCost = left.toLong() * (left + 1L) / 2L
            val rightCost = right.toLong() * (right + 1L) / 2L
            val transitionMadness = (leftCost + rightCost) % mod

            var madnessTerm = previousMadness * transitionWays % mod
            madnessTerm += baseWays * transitionMadness % mod
            if (madnessTerm >= mod) madnessTerm -= mod
            madnessTerm = madnessTerm * interleavings % mod

            totalMadness += madnessTerm
            if (totalMadness >= mod) totalMadness -= mod
        }

        rawWays[size] = totalWays
        rawMadness[size] = totalMadness
    }

    val runWays = LongArray(m + 1)
    val runMadness = LongArray(m + 1)
    for (size in 0..m) {
        runWays[size] = rawWays[size] * inverseFactorial[size] % mod
        runMadness[size] = rawMadness[size] * inverseFactorial[size] % mod
    }

    val compositionWays = Array(m + 1) { LongArray(m + 1) }
    val compositionMadness = Array(m + 1) { LongArray(m + 1) }
    compositionWays[0][0] = 1L

    for (runs in 1..m) {
        for (occupied in runs..m) {
            var ways = 0L
            var madness = 0L
            val maxLastRun = occupied - (runs - 1)

            for (lastRun in 1..maxLastRun) {
                val previousOccupied = occupied - lastRun
                val previousWays = compositionWays[runs - 1][previousOccupied]
                val previousMadness = compositionMadness[runs - 1][previousOccupied]

                val waysTerm = previousWays * runWays[lastRun] % mod
                ways += waysTerm
                if (ways >= mod) ways -= mod

                var madnessTerm = previousMadness * runWays[lastRun] % mod
                madnessTerm += previousWays * runMadness[lastRun] % mod
                if (madnessTerm >= mod) madnessTerm -= mod

                madness += madnessTerm
                if (madness >= mod) madness -= mod
            }

            compositionWays[runs][occupied] = ways
            compositionMadness[runs][occupied] = madness
        }
    }

    val availableGaps = n - m + 1
    var answer = 0L
    val maxRuns = minOf(m, availableGaps)

    for (runs in 1..maxRuns) {
        val placements = choose[availableGaps][runs]
        val term = placements * compositionMadness[runs][m] % mod
        answer += term
        if (answer >= mod) answer -= mod
    }

    answer = answer * factorial[m] % mod
    print(answer)
}

import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0L
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
