private lateinit var modulusHolder: LongArray

private fun mulMod(a: Long, b: Long): Long {
    return (a * b) % modulusHolder[0]
}

private fun powMod(baseValue: Long, exponentValue: Int): Long {
    val mod = modulusHolder[0]
    var base = baseValue % mod
    var exponent = exponentValue
    var result = 1L

    while (exponent > 0) {
        if ((exponent and 1) != 0) {
            result = mulMod(result, base)
        }
        base = mulMod(base, base)
        exponent = exponent shr 1
    }
    return result
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextLong().toInt()
    val m = fs.nextLong().toInt()
    val mod = fs.nextLong()
    modulusHolder = longArrayOf(mod)

    val binom = Array(m + 1) { LongArray(m + 1) }
    binom[0][0] = 1L
    for (i in 1..m) {
        binom[i][0] = 1L
        binom[i][i] = 1L
        for (j in 1 until i) {
            binom[i][j] = (binom[i - 1][j - 1] + binom[i - 1][j]) % mod
        }
    }

    val pow2 = LongArray(m + 1)
    pow2[0] = 1L
    for (i in 1..m) {
        pow2[i] = (pow2[i - 1] * 2L) % mod
    }

    val count = LongArray(m + 1)
    val madness = LongArray(m + 1)
    count[0] = 1L

    for (k in 1..m) {
        count[k] = mulMod(pow2[k], powMod((k + 1).toLong(), k - 1))

        var total = 0L
        for (left in 0 until k) {
            val right = k - 1 - left

            val previousMadness = (
                mulMod(madness[left], count[right]) +
                    mulMod(count[left], madness[right])
                ) % mod

            val repeatedPrevious = mulMod((k + 1).toLong(), previousMadness)

            val leftDistance = left.toLong() * (left + 1L) / 2L
            val rightDistance = right.toLong() * (right + 1L) / 2L
            val lastDistanceSum = (leftDistance + rightDistance) % mod

            val lastMadness = mulMod(
                mulMod(count[left], count[right]),
                lastDistanceSum
            )

            val contribution = mulMod(
                binom[k - 1][left],
                (repeatedPrevious + lastMadness) % mod
            )

            total += contribution
            if (total >= mod) total %= mod
        }
        madness[k] = total % mod
    }

    val emptyCount = n - m
    val blockCount = emptyCount + 1
    var answer = 0L

    for (k in 1..m) {
        val remaining = m - k

        val otherBlocksCount = when {
            remaining == 0 -> 1L
            emptyCount == 0 -> 0L
            else -> {
                var value = mulMod(
                    emptyCount.toLong(),
                    powMod((remaining + emptyCount).toLong(), remaining - 1)
                )
                value = mulMod(value, pow2[remaining])
                value
            }
        }

        val contribution = mulMod(
            binom[m][k],
            mulMod(madness[k], otherBlocksCount)
        )

        answer += contribution
        if (answer >= mod) answer %= mod
    }

    answer = mulMod(answer % mod, blockCount.toLong())
    print(answer)
}
